import 'package:flutter_test/flutter_test.dart';
import 'package:romdoul_bank/models/khqr.dart';

// Generated by tools/make_sample_khqr.py (fictional merchants).
const staticKhr =
    '00020101021129190015sokha_cafe@rdlb5204599953031165802KH5908DARA SOK6010Phnom Penh63049871';
const dynamicUsd =
    '00020101021230460015sokha_cafe@rdlb010712345670212Romdoul Bank52045999530384054042.505802KH5910SOKHA CAFE6010Phnom Penh62250108INV-10240309Riverside9934001317950107432830113410244480000063045DA2';
const expiredUsd =
    '00020101021230460015sokha_cafe@rdlb010712345670212Romdoul Bank52045999530384054045.005802KH5908OLD SHOP6006Kampot99340013179501074328401131600000000000630498DB';

void main() {
  test('CRC-16/CCITT-FALSE check value', () {
    expect(KhqrParser.crc16('123456789'), '29B1');
  });

  test('static individual KHQR (user types amount)', () {
    final q = KhqrParser.parse(staticKhr);
    expect(q.isDynamic, isFalse);
    expect(q.isMerchant, isFalse);
    expect(q.hasAmount, isFalse);
    expect(q.currency, KhqrCurrency.khr);
    expect(q.merchantName, 'DARA SOK');
    expect(q.accountId, 'sokha_cafe@rdlb');
    expect(q.initials, 'DS');
  });

  test('dynamic merchant KHQR (amount locked)', () {
    final q = KhqrParser.parse(dynamicUsd);
    expect(q.isDynamic, isTrue);
    expect(q.isMerchant, isTrue);
    expect(q.amount, 2.5);
    expect(q.currency, KhqrCurrency.usd);
    expect(q.billNumber, 'INV-1024');
    expect(q.storeLabel, 'Riverside');
    expect(q.acquiringBank, 'Romdoul Bank');
    expect(q.isExpired, isFalse);
  });

  test('expired KHQR is detected', () {
    expect(KhqrParser.parse(expiredUsd).isExpired, isTrue);
  });

  test('tampered amount fails checksum', () {
    final tampered = dynamicUsd.replaceFirst('54042.50', '54049.50');
    expect(() => KhqrParser.parse(tampered),
        throwsA(isA<KhqrException>().having((e) => e.reason, 'reason', KhqrError.badChecksum)));
  });

  test('non-KHQR content is rejected', () {
    expect(() => KhqrParser.parse('https://example.com'),
        throwsA(isA<KhqrException>().having((e) => e.reason, 'reason', KhqrError.notKhqr)));
  });
}
